const cfg = $('Config').first().json;
const trigger = $('Cuando lo llama el 01').first().json || {};
const incoming = $input.first().json || {};
const input = Object.assign({}, incoming, trigger);
const tz = String(cfg.timezone || 'America/Caracas');
const now = DateTime.now().setZone(tz);
let periodo = String(input.periodo || '').trim();
if (!/^[0-9]{4}-[0-9]{2}$/.test(periodo)) {
  periodo = now.toFormat('yyyy-MM');
}
const rawTipo = String(input.tipo || '').toLowerCase().trim();
const rawEstilo = String(input.estilo || '').toLowerCase().trim();
const blob = `${rawTipo} ${rawEstilo}`.trim();
const porDia = /(dia|diario|d[ií]as|por dia|por día|rendimiento diario|time series|barras por dia)/.test(blob);
const porOrigen = /(origen|recurrent|nuevos?\s*vs|nuevos y recurrent|recurrentes y nuevos)/.test(blob);
let tipo = 'embudo_mes';
if (porDia) tipo = 'reservas_dia';
else if (porOrigen) tipo = 'reservas_origen';
let estilo = 'barras';
if (/(pie|torta|donut|doughnut|circular|pastel)/.test(blob)) estilo = 'pie';
else if (/(linea|línea|lineas|líneas|lineal)/.test(blob)) estilo = 'lineas';
const estiloPedido = estilo;
if (tipo === 'reservas_dia' && estilo === 'pie') estilo = 'barras';
if (tipo !== 'reservas_dia' && estilo === 'lineas') estilo = 'barras';
const chatId = String(input.telegram_chat_id || '').trim();
if (!chatId) {
  throw new Error('Falta telegram_chat_id');
}
return [{ json: { telegram_chat_id: chatId, tipo, estilo, estiloPedido, periodo, timezone: tz } }];

const cfg = $('Config').first().json;
const meta = $('Normalizar').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && (r.periodo || r.label));
const width = Number(cfg.chartWidth || 600);
const height = Number(cfg.chartHeight || 320);
const tick = { fontColor: '#444444' };
const grid = { color: 'rgba(0,0,0,0.08)' };
const scalesV2 = {
  xAxes: [{ ticks: tick, gridLines: grid }],
  yAxes: [{ ticks: { ...tick, beginAtZero: true }, gridLines: grid }],
};
const COLOR_NUEVOS = '#3b82f6';
const COLOR_REC = '#f97316';
const COLOR_CONV = '#94a3b8';

const sum = (xs) => xs.reduce((a, b) => a + b, 0);

const chartOf = (type, labels, datasets, title) => {
  const cartesian = type === 'bar' || type === 'horizontalBar' || type === 'line';
  const options = {
    legend: { position: 'bottom', labels: { fontColor: '#333333' } },
    title: { display: true, text: title, fontColor: '#222222' },
  };
  if (cartesian) options.scales = scalesV2;
  return { type, data: { labels, datasets }, options };
};

const lineDs = (label, data, color) => ({
  label,
  data,
  borderColor: color,
  backgroundColor: color,
  fill: false,
  pointRadius: 3,
});

const barDs = (label, data, color) => ({
  label,
  data,
  backgroundColor: color,
});

let chart;
let caption;
const estilo = meta.estilo || 'barras';
const coerced = meta.estiloPedido && meta.estiloPedido !== estilo
  ? ` Estilo ${meta.estiloPedido} no aplica a este tipo; se uso ${estilo}.`
  : '';

if (meta.tipo === 'reservas_dia') {
  const labels = rows.map((r) => String(r.label));
  const conversaciones = rows.map((r) => Number(r.conversaciones || 0));
  const nuevos = rows.map((r) => Number(r.reservaron_nuevos || 0));
  const recurrentes = rows.map((r) => Number(r.reservaron_recurrentes || 0));
  const totalN = sum(nuevos);
  const totalR = sum(recurrentes);
  const title = 'Cierres diarios ' + meta.periodo;
  if (estilo === 'lineas') {
    chart = chartOf('line', labels, [
      lineDs('Conversaciones', conversaciones, COLOR_CONV),
      lineDs('Nuevos', nuevos, COLOR_NUEVOS),
      lineDs('Recurrentes', recurrentes, COLOR_REC),
    ], title);
  } else {
    chart = chartOf('bar', labels, [
      barDs('Conversaciones', conversaciones, COLOR_CONV),
      barDs('Nuevos', nuevos, COLOR_NUEVOS),
      barDs('Recurrentes', recurrentes, COLOR_REC),
    ], title);
  }
  caption = 'Rendimiento diario ' + meta.periodo + ' (hora Venezuela). Nuevos: ' + totalN + '. Recurrentes: ' + totalR + '.' + coerced;
} else {
  const r = rows[0] || {};
  const conversaciones = Number(r.conversaciones || 0);
  const reservaron = Number(r.reservaron || 0);
  const nuevos = Number(r.reservaron_nuevos || 0);
  const recurrentes = Number(r.reservaron_recurrentes || 0);
  const preguntaron = Number(r.preguntaron_sin_cerrar || 0);
  const noResp = Number(r.no_respondieron || 0);
  const enProceso = Number(r.en_proceso || 0);
  const pct = r.pct_reservaciones == null ? '' : String(r.pct_reservaciones);

  if (meta.tipo === 'reservas_origen') {
    const labels = ['Nuevos', 'Recurrentes'];
    const data = [nuevos, recurrentes];
    const title = 'Nuevos vs recurrentes ' + meta.periodo;
    if (estilo === 'pie') {
      chart = chartOf('doughnut', labels, [{
        data,
        backgroundColor: [COLOR_NUEVOS, COLOR_REC],
      }], title);
    } else {
      chart = chartOf('bar', labels, [{
        label: 'Cierres',
        data,
        backgroundColor: [COLOR_NUEVOS, COLOR_REC],
      }], title);
    }
    caption = 'Cierres ' + meta.periodo + '. Nuevos: ' + nuevos + '. Recurrentes: ' + recurrentes + '. Total: ' + reservaron + '.' + coerced;
  } else {
    const labels = ['Reservaron', 'Preguntaron sin cerrar', 'No respondieron', 'En proceso'];
    const data = [reservaron, preguntaron, noResp, enProceso];
    const colors = ['#22c55e', '#f59e0b', '#ef4444', '#3b82f6'];
    const title = 'Embudo WhatsApp ' + meta.periodo;
    if (estilo === 'pie') {
      chart = chartOf('doughnut', labels, [{ data, backgroundColor: colors }], title);
    } else {
      chart = chartOf('bar', labels, [{ label: 'Leads ' + meta.periodo, data, backgroundColor: colors }], title);
    }
    caption = 'Embudo ' + meta.periodo + '. Conversaciones nuevas: ' + conversaciones + (pct !== '' ? '. % reservas nuevas: ' + pct : '') + '. Cierres del mes: ' + reservaron + ' (nuevos: ' + nuevos + ', recurrentes: ' + recurrentes + ').' + coerced;
  }
}

return [{
  json: {
    telegram_chat_id: meta.telegram_chat_id,
    tipo: meta.tipo,
    estilo,
    periodo: meta.periodo,
    caption,
    httpBody: {
      backgroundColor: 'white',
      width,
      height,
      format: 'png',
      chart,
    },
  },
}];
